using System.Data;
using System.Globalization;
using System.Text;
using HospitalManagementSystem.Helpers;
using HospitalManagementSystem.Models.Common;
using HospitalManagementSystem.Models.MP10_Laboratory;
using HospitalManagementSystem.Repositories.Common;
using MySqlConnector;

namespace HospitalManagementSystem.Repositories.MP10_Laboratory
{
    /// <summary>
    /// All SQL for the Laboratory Test Catalog and Result Entry (MP10, Step 14).
    ///
    /// CATALOG
    ///   - Test ID TST-XXX is generated by GeneratorHelper inside the save transaction (so it is unique and has no gaps);
    ///   - the test name is unique; the price is above 0 with at most 2 decimals;
    ///   - the normal range is two TEXT values: both numbers (12.0 / 17.5) or both words (Negative / Negative);
    ///   - a test that already has lab orders cannot be deleted (the orders and results are kept for the records).
    ///
    /// RESULT ENTRY  (SaveResult - one transaction)
    ///   1. lock the order row; it must still be Pending and must not have a result yet;
    ///   2. re-check every rule (value required and numeric for a numeric range, test date/time not in the future,
    ///      Tested By required, Verified By required when the test requires verification);
    ///   3. RE-COMPUTE the abnormal flag from the catalog range (RangeEvaluator) - the screen's flag is only a preview;
    ///   4. generate LR-YYYYMMDD-XXX, insert lab_results (is_abnormal is a snapshot) and set the order to Completed.
    /// If anything fails everything is rolled back, including the id number.
    /// </summary>
    public class LaboratoryRepository
    {
        // lab_orders.status values
        public const string StatusPending = "Pending";
        public const string StatusCompleted = "Completed";

        private const string TestSelect =
            "SELECT t.test_id, t.test_name, t.category, t.sample_type, " +
            "       t.price, t.normal_range_low, t.normal_range_high, t.unit, t.turnaround_hours, t.requires_verification " +
            "FROM lab_tests t ";

        // ------------------------------------------------------------------
        // Lists
        // ------------------------------------------------------------------

        // The values already in use; the drop-downs also accept a newly typed one.
        public List<LookupItem> GetCategories() => LookupRepository.Distinct("lab_tests", "category");

        public List<LookupItem> GetSampleTypes() => LookupRepository.Distinct("lab_tests", "sample_type");

        /// <summary>Active staff who can be named as Tested By / Verified By (Lab Technician, Doctor, Administrator).</summary>
        public List<LookupItem> GetStaff() =>
            LoadLookup("SELECT u.user_id AS id, u.full_name AS name FROM users u " +
                       "WHERE u.is_active = 1 AND u.role IN ('Lab Technician', 'Doctor', 'Administrator') ORDER BY u.full_name");

        private static List<LookupItem> LoadLookup(string sql)
        {
            DataTable table = DatabaseHelper.ExecuteQuery(sql);
            return table.Rows.Cast<DataRow>()
                .Select(r => new LookupItem { Id = DatabaseHelper.GetString(r, "id"), Name = DatabaseHelper.GetString(r, "name") })
                .ToList();
        }

        /// <summary>Adds "AND (col1 LIKE @w0 OR col2 LIKE @w0) AND (...)" for every word typed in a search box.</summary>
        private static void AppendWords(StringBuilder sql, List<MySqlParameter> parameters, string? text, params string[] columns)
        {
            if (string.IsNullOrWhiteSpace(text)) return;
            string[] words = text.Split(' ', StringSplitOptions.RemoveEmptyEntries);
            for (int i = 0; i < words.Length; i++)
            {
                string name = "@w" + i.ToString(CultureInfo.InvariantCulture);
                sql.Append(" AND (").Append(string.Join(" OR ", columns.Select(c => c + " LIKE " + name))).Append(')');
                string escaped = words[i].Replace("\\", "\\\\").Replace("%", "\\%").Replace("_", "\\_");
                parameters.Add(DatabaseHelper.Param(name, "%" + escaped + "%"));
            }
        }

        // ------------------------------------------------------------------
        // Catalog
        // ------------------------------------------------------------------

        public List<LabTestRecord> GetTests(string? text)
        {
            var sql = new StringBuilder(TestSelect + "WHERE 1 = 1");
            var parameters = new List<MySqlParameter>();
            AppendWords(sql, parameters, text, "t.test_id", "t.test_name", "t.category", "t.sample_type");
            sql.Append(" ORDER BY t.test_id");
            DataTable table = DatabaseHelper.ExecuteQuery(sql.ToString(), parameters.ToArray());
            return table.Rows.Cast<DataRow>().Select(ReadTest).ToList();
        }

        private static LabTestRecord ReadTest(DataRow row) => new LabTestRecord
        {
            TestId = DatabaseHelper.GetString(row, "test_id"),
            TestName = DatabaseHelper.GetString(row, "test_name"),
            Category = DatabaseHelper.GetString(row, "category"),
            SampleType = DatabaseHelper.GetString(row, "sample_type"),
            Price = DatabaseHelper.GetDecimal(row, "price"),
            NormalRangeLow = DatabaseHelper.GetString(row, "normal_range_low"),
            NormalRangeHigh = DatabaseHelper.GetString(row, "normal_range_high"),
            Unit = DatabaseHelper.GetString(row, "unit"),
            TurnaroundHours = DatabaseHelper.GetInt(row, "turnaround_hours"),
            RequiresVerification = DatabaseHelper.GetBool(row, "requires_verification")
        };

        /// <summary>The catalog rules that need no database. The form shows the same messages next to the fields.</summary>
        public static List<string> ValidateTest(LabTestInput input)
        {
            var errors = new List<string>();
            string name = (input.TestName ?? string.Empty).Trim();
            string low = (input.NormalRangeLow ?? string.Empty).Trim();
            string high = (input.NormalRangeHigh ?? string.Empty).Trim();
            string unit = (input.Unit ?? string.Empty).Trim();

            if (name.Length == 0) errors.Add("Enter the test name.");
            else if (name.Length > LaboratoryRules.MaxTestName) errors.Add($"The test name can have at most {LaboratoryRules.MaxTestName} characters.");

            string category = (input.Category ?? string.Empty).Trim();
            string sample = (input.SampleType ?? string.Empty).Trim();
            if (category.Length == 0) errors.Add("Choose or type the category.");
            else if (category.Length > LaboratoryRules.MaxCategory) errors.Add($"The category can have at most {LaboratoryRules.MaxCategory} characters.");
            if (sample.Length == 0) errors.Add("Choose or type the sample type.");
            else if (sample.Length > LaboratoryRules.MaxSampleType) errors.Add($"The sample type can have at most {LaboratoryRules.MaxSampleType} characters.");

            if (input.Price <= 0 || input.Price > LaboratoryRules.PriceMax)
                errors.Add($"The price must be greater than 0 and at most {LaboratoryRules.PriceMax:N0}.");
            else if (Math.Round(input.Price, 2) != input.Price)
                errors.Add("The price can have at most 2 decimal places.");

            if (low.Length == 0 || high.Length == 0)
                errors.Add("Enter both the low and the high normal range. For a descriptive test (for example Negative) type the same text in both.");
            else
            {
                bool lowNumeric = RangeEvaluator.TryParseNumber(low, out decimal lowNumber);
                bool highNumeric = RangeEvaluator.TryParseNumber(high, out decimal highNumber);
                if (lowNumeric != highNumeric)
                    errors.Add("The normal range must be two numbers (for example 12.0 and 17.5) or two words (for example Negative and Negative), not one of each.");
                else if (lowNumeric && lowNumber > highNumber)
                    errors.Add("The low normal range cannot be greater than the high normal range.");
            }
            if (low.Length > LaboratoryRules.MaxRange || high.Length > LaboratoryRules.MaxRange)
                errors.Add($"Each normal range value can have at most {LaboratoryRules.MaxRange} characters.");
            if (unit.Length > LaboratoryRules.MaxUnit) errors.Add($"The unit can have at most {LaboratoryRules.MaxUnit} characters.");

            if (input.TurnaroundHours < 1 || input.TurnaroundHours > LaboratoryRules.TurnaroundMax)
                errors.Add($"The turnaround time must be a whole number of hours from 1 to {LaboratoryRules.TurnaroundMax}.");

            return errors;
        }

        public LabTestRecord SaveTest(LabTestInput input)
        {
            List<string> errors = ValidateTest(input);
            if (errors.Count > 0) throw new InvalidOperationException(string.Join(Environment.NewLine, errors));

            return DatabaseHelper.ExecuteInTransaction((conn, tx) =>
            {
                string name = input.TestName.Trim();

                DataTable duplicate = DatabaseHelper.ExecuteQuery(conn, tx,
                    "SELECT test_id FROM lab_tests WHERE test_name = @name AND test_id <> @id LIMIT 1",
                    DatabaseHelper.Param("@name", name), DatabaseHelper.Param("@id", input.TestId));
                if (duplicate.Rows.Count > 0)
                    throw new InvalidOperationException($"A test named \"{name}\" already exists ({DatabaseHelper.GetString(duplicate.Rows[0], "test_id")}). The test name must be unique.");

                string id = input.TestId;
                if (id.Length == 0)
                {
                    id = GeneratorHelper.Generate(GeneratorHelper.Prefix.LabTest, conn, tx);
                    DatabaseHelper.ExecuteNonQuery(conn, tx,
                        "INSERT INTO lab_tests (test_id, test_name, category, sample_type, price, normal_range_low, normal_range_high, unit, turnaround_hours, requires_verification) " +
                        "VALUES (@id, @name, @category, @sample, @price, @low, @high, @unit, @hours, @verify)",
                        TestParams(input).Append(DatabaseHelper.Param("@id", id)).ToArray());
                }
                else
                {
                    object? exists = DatabaseHelper.ExecuteScalar(conn, tx,
                        "SELECT test_id FROM lab_tests WHERE test_id = @id FOR UPDATE", DatabaseHelper.Param("@id", id));
                    if (exists == null || exists == DBNull.Value)
                        throw new InvalidOperationException("This test no longer exists. The list will be refreshed.");

                    DatabaseHelper.ExecuteNonQuery(conn, tx,
                        "UPDATE lab_tests SET test_name = @name, category = @category, sample_type = @sample, price = @price, " +
                        "  normal_range_low = @low, normal_range_high = @high, unit = @unit, turnaround_hours = @hours, requires_verification = @verify " +
                        "WHERE test_id = @id",
                        TestParams(input).Append(DatabaseHelper.Param("@id", id)).ToArray());
                }

                DataTable saved = DatabaseHelper.ExecuteQuery(conn, tx, TestSelect + "WHERE t.test_id = @id", DatabaseHelper.Param("@id", id));
                return ReadTest(saved.Rows[0]);
            });
        }

        private static IEnumerable<MySqlParameter> TestParams(LabTestInput input)
        {
            var list = new List<MySqlParameter>();
            list.Add(DatabaseHelper.Param("@name", input.TestName.Trim()));
            list.Add(DatabaseHelper.Param("@category", input.Category.Trim()));
            list.Add(DatabaseHelper.Param("@sample", input.SampleType.Trim()));
            list.Add(DatabaseHelper.Param("@price", input.Price));
            list.Add(DatabaseHelper.Param("@low", input.NormalRangeLow.Trim()));
            list.Add(DatabaseHelper.Param("@high", input.NormalRangeHigh.Trim()));
            list.Add(DatabaseHelper.Param("@unit", string.IsNullOrWhiteSpace(input.Unit) ? null : input.Unit.Trim()));
            list.Add(DatabaseHelper.Param("@hours", input.TurnaroundHours));
            list.Add(DatabaseHelper.Param("@verify", input.RequiresVerification ? 1 : 0));
            return list;
        }

        /// <summary>Deletes a test that was never ordered; otherwise explains why not.</summary>
        public void DeleteTest(string testId)
        {
            DatabaseHelper.ExecuteInTransaction((conn, tx) =>
            {
                object? name = DatabaseHelper.ExecuteScalar(conn, tx,
                    "SELECT test_name FROM lab_tests WHERE test_id = @id FOR UPDATE", DatabaseHelper.Param("@id", testId));
                if (name == null || name == DBNull.Value)
                    throw new InvalidOperationException("This test no longer exists. The list will be refreshed.");

                long orders = DatabaseHelper.ExecuteScalar<long>(conn, tx,
                    "SELECT COUNT(*) FROM lab_orders WHERE test_id = @id", DatabaseHelper.Param("@id", testId));
                if (orders > 0)
                    throw new InvalidOperationException(
                        $"{name} cannot be deleted because it has {orders} lab order(s). " +
                        "Tests that were ordered are kept for the records; change the price or the normal range instead.");

                DatabaseHelper.ExecuteNonQuery(conn, tx, "DELETE FROM lab_tests WHERE test_id = @id", DatabaseHelper.Param("@id", testId));
            });
        }

        // ------------------------------------------------------------------
        // Pending orders and result entry
        // ------------------------------------------------------------------

        /// <summary>Pending orders, STAT first, then Urgent, then Routine; oldest first inside each group.</summary>
        public List<PendingOrder> GetPendingOrders(string? text)
        {
            var sql = new StringBuilder(
                "SELECT o.order_id, p.patient_id, CONCAT(p.first_name, ' ', p.last_name) AS patient_name, " +
                "       t.test_id, t.test_name, t.sample_type, t.normal_range_low, t.normal_range_high, t.unit, " +
                "       t.requires_verification, o.urgency, o.ordered_at, " +
                "       COALESCE(CONCAT(d.first_name, ' ', d.last_name), '') AS doctor_name " +
                "FROM lab_orders o " +
                "JOIN patients p ON p.patient_id = o.patient_id " +
                "JOIN lab_tests t ON t.test_id = o.test_id " +
                "LEFT JOIN doctors d ON d.doctor_id = o.ordered_by_doctor_id " +
                "WHERE o.status = '" + StatusPending + "'");
            var parameters = new List<MySqlParameter>();
            AppendWords(sql, parameters, text, "o.order_id", "p.patient_id", "p.first_name", "p.last_name", "t.test_name");
            sql.Append($" ORDER BY FIELD(o.urgency, 'STAT', 'Urgent', 'Routine'), o.ordered_at ASC, o.order_id ASC LIMIT {LaboratoryRules.OrderListLimit}");

            DataTable table = DatabaseHelper.ExecuteQuery(sql.ToString(), parameters.ToArray());
            return table.Rows.Cast<DataRow>().Select(row => new PendingOrder
            {
                OrderId = DatabaseHelper.GetString(row, "order_id"),
                PatientId = DatabaseHelper.GetString(row, "patient_id"),
                PatientName = DatabaseHelper.GetString(row, "patient_name"),
                TestId = DatabaseHelper.GetString(row, "test_id"),
                TestName = DatabaseHelper.GetString(row, "test_name"),
                SampleTypeName = DatabaseHelper.GetString(row, "sample_type"),
                NormalRangeLow = DatabaseHelper.GetString(row, "normal_range_low"),
                NormalRangeHigh = DatabaseHelper.GetString(row, "normal_range_high"),
                Unit = DatabaseHelper.GetString(row, "unit"),
                RequiresVerification = DatabaseHelper.GetBool(row, "requires_verification"),
                UrgencyName = DatabaseHelper.GetString(row, "urgency"),
                OrderedAt = DatabaseHelper.GetNullableDate(row, "ordered_at") ?? DateTime.Now,
                DoctorName = DatabaseHelper.GetString(row, "doctor_name")
            }).ToList();
        }

        /// <summary>The result-entry rules that need no database (the repository calls this again on save).</summary>
        public static List<string> ValidateResult(LabResultInput input, string low, string high, bool requiresVerification)
        {
            var errors = new List<string>();
            string value = (input.ResultValue ?? string.Empty).Trim();

            if (value.Length == 0) errors.Add("Enter the result value.");
            else if (value.Length > LaboratoryRules.MaxResultValue) errors.Add($"The result value can have at most {LaboratoryRules.MaxResultValue} characters.");
            else if (RangeEvaluator.IsNumericRange(low, high) && !RangeEvaluator.TryParseNumber(value, out _))
                errors.Add("This test has a numeric normal range, so the result value must be a number (for example 13.5).");

            if ((input.Findings ?? string.Empty).Length > LaboratoryRules.MaxFindings)
                errors.Add($"The findings can have at most {LaboratoryRules.MaxFindings} characters.");

            if (input.TestDateTime > DateTime.Now) errors.Add("The test date and time cannot be in the future.");

            if (input.TestedByUserId <= 0) errors.Add("Choose who tested the sample (Tested By).");

            if (requiresVerification && !(input.VerifiedByUserId.HasValue && input.VerifiedByUserId.Value > 0))
                errors.Add("This test requires verification. Choose who verified the result (Verified By) before it can be marked Completed.");
            else if (input.VerifiedByUserId.HasValue && input.VerifiedByUserId.Value > 0 && input.VerifiedByUserId.Value == input.TestedByUserId)
                errors.Add("The verifier must be a different person from the one who tested the sample.");

            return errors;
        }

        public LabResultSaved SaveResult(LabResultInput input)
        {
            return DatabaseHelper.ExecuteInTransaction((conn, tx) =>
            {
                DataTable order = DatabaseHelper.ExecuteQuery(conn, tx,
                    "SELECT o.order_id, o.status, t.test_name, t.normal_range_low, t.normal_range_high, t.requires_verification " +
                    "FROM lab_orders o JOIN lab_tests t ON t.test_id = o.test_id WHERE o.order_id = @id FOR UPDATE",
                    DatabaseHelper.Param("@id", input.OrderId));
                if (order.Rows.Count == 0)
                    throw new InvalidOperationException("This lab order no longer exists. The list will be refreshed.");

                DataRow row = order.Rows[0];
                string orderCode = input.OrderId;
                if (DatabaseHelper.GetString(row, "status") != StatusPending)
                    throw new InvalidOperationException($"Order {orderCode} is no longer pending - a result was already entered or the order was cancelled. The list will be refreshed.");

                long existing = DatabaseHelper.ExecuteScalar<long>(conn, tx,
                    "SELECT COUNT(*) FROM lab_results WHERE order_id = @id", DatabaseHelper.Param("@id", input.OrderId));
                if (existing > 0)
                    throw new InvalidOperationException($"Order {orderCode} already has a result. Only one result can be entered per order.");

                string low = DatabaseHelper.GetString(row, "normal_range_low");
                string high = DatabaseHelper.GetString(row, "normal_range_high");
                bool requiresVerification = DatabaseHelper.GetBool(row, "requires_verification");

                List<string> errors = ValidateResult(input, low, high, requiresVerification);
                if (errors.Count > 0) throw new InvalidOperationException(string.Join(Environment.NewLine, errors));

                string value = input.ResultValue.Trim();
                bool abnormal = RangeEvaluator.Evaluate(value, low, high).IsAbnormal;

                string resultId = GeneratorHelper.Generate(GeneratorHelper.Prefix.LabResult, conn, tx);
                DatabaseHelper.ExecuteNonQuery(conn, tx,
                    "INSERT INTO lab_results (result_id, order_id, result_value, is_abnormal, findings, tested_by_user_id, verified_by_user_id, test_datetime) " +
                    "VALUES (@id, @order, @value, @abnormal, @findings, @tested, @verified, @when)",
                    DatabaseHelper.Param("@id", resultId),
                    DatabaseHelper.Param("@order", input.OrderId),
                    DatabaseHelper.Param("@value", value),
                    DatabaseHelper.Param("@abnormal", abnormal ? 1 : 0),
                    DatabaseHelper.Param("@findings", string.IsNullOrWhiteSpace(input.Findings) ? null : input.Findings.Trim()),
                    DatabaseHelper.Param("@tested", input.TestedByUserId),
                    DatabaseHelper.Param("@verified", input.VerifiedByUserId.HasValue && input.VerifiedByUserId.Value > 0 ? input.VerifiedByUserId.Value : (int?)null),
                    DatabaseHelper.Param("@when", input.TestDateTime));

                DatabaseHelper.ExecuteNonQuery(conn, tx,
                    "UPDATE lab_orders SET status = @done WHERE order_id = @id",
                    DatabaseHelper.Param("@done", StatusCompleted), DatabaseHelper.Param("@id", input.OrderId));

                object? patient = DatabaseHelper.ExecuteScalar(conn, tx,
                    "SELECT patient_id FROM lab_orders WHERE order_id = @id", DatabaseHelper.Param("@id", input.OrderId));
                AuditHelper.Log(conn, tx, AuditHelper.Create, AuditHelper.LabResult, resultId, patient as string,
                    $"Order {orderCode}, {DatabaseHelper.GetString(row, "test_name")}: {value}{(abnormal ? " (ABNORMAL)" : string.Empty)}");

                return new LabResultSaved
                {
                    ResultId = resultId,
                    OrderId = orderCode,
                    TestName = DatabaseHelper.GetString(row, "test_name"),
                    IsAbnormal = abnormal
                };
            });
        }

        // ------------------------------------------------------------------
        // History
        // ------------------------------------------------------------------

        public List<LabResultRecord> GetResults(string? text, bool abnormalOnly)
        {
            var sql = new StringBuilder(
                "SELECT r.result_id, r.order_id, p.patient_id, CONCAT(p.first_name, ' ', p.last_name) AS patient_name, " +
                "       t.test_name, r.result_value, t.unit, t.normal_range_low, t.normal_range_high, r.is_abnormal, r.findings, " +
                "       tu.full_name AS tested_by, vu.full_name AS verified_by, r.test_datetime " +
                "FROM lab_results r " +
                "JOIN lab_orders o ON o.order_id = r.order_id " +
                "JOIN patients p ON p.patient_id = o.patient_id " +
                "JOIN lab_tests t ON t.test_id = o.test_id " +
                "JOIN users tu ON tu.user_id = r.tested_by_user_id " +
                "LEFT JOIN users vu ON vu.user_id = r.verified_by_user_id " +
                "WHERE 1 = 1");
            var parameters = new List<MySqlParameter>();
            if (abnormalOnly) sql.Append(" AND r.is_abnormal = 1");
            AppendWords(sql, parameters, text, "r.result_id", "r.order_id", "p.patient_id", "p.first_name", "p.last_name", "t.test_name");
            sql.Append($" ORDER BY r.test_datetime DESC, r.result_id DESC LIMIT {LaboratoryRules.HistoryLimit}");

            DataTable table = DatabaseHelper.ExecuteQuery(sql.ToString(), parameters.ToArray());
            return table.Rows.Cast<DataRow>().Select(row => new LabResultRecord
            {
                ResultId = DatabaseHelper.GetString(row, "result_id"),
                OrderId = DatabaseHelper.GetString(row, "order_id"),
                PatientId = DatabaseHelper.GetString(row, "patient_id"),
                PatientName = DatabaseHelper.GetString(row, "patient_name"),
                TestName = DatabaseHelper.GetString(row, "test_name"),
                ResultValue = DatabaseHelper.GetString(row, "result_value"),
                Unit = DatabaseHelper.GetString(row, "unit"),
                NormalRangeLow = DatabaseHelper.GetString(row, "normal_range_low"),
                NormalRangeHigh = DatabaseHelper.GetString(row, "normal_range_high"),
                IsAbnormal = DatabaseHelper.GetBool(row, "is_abnormal"),
                Findings = DatabaseHelper.GetString(row, "findings"),
                TestedBy = DatabaseHelper.GetString(row, "tested_by"),
                VerifiedBy = DatabaseHelper.GetString(row, "verified_by"),
                TestDateTime = DatabaseHelper.GetNullableDate(row, "test_datetime") ?? DateTime.Now
            }).ToList();
        }
    }
}